import { useState, useEffect } from "react";
import { ArrowLeft, ArrowRight, RotateCw, ExternalLink, ZoomIn, ZoomOut, Target, RefreshCw } from "lucide-react";
import { focusBrowser, getBrowserState, openExternalUrl, setBrowserZoom } from "../lib/browserTauri";
import type { BrowserTab } from "../lib/types";

interface BrowserToolbarProps {
  tab: BrowserTab;
  onNavigate: (url: string) => void;
  onReload: () => void;
  onGoBack?: () => void;
  onGoForward?: () => void;
}

export function BrowserToolbar({
  tab,
  onNavigate,
  onReload,
  onGoBack,
  onGoForward,
}: BrowserToolbarProps) {
  const [inputUrl, setInputUrl] = useState(tab.url);
  const [zoomFactor, setZoomFactor] = useState(1.0);

  useEffect(() => {
    setInputUrl(tab.url);
  }, [tab.url]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    let url = inputUrl.trim();
    if (!url) return;
    if (!url.startsWith("http://") && !url.startsWith("https://") && url !== "about:blank") {
      if (url.startsWith("localhost") || url.startsWith("127.0.0.1")) {
        url = `http://${url}`;
      } else {
        url = `https://${url}`;
      }
    }
    onNavigate(url);
  };

  const handleExternalOpen = () => {
    if (tab.url && tab.url !== "about:blank") {
      void openExternalUrl(tab.url);
    }
  };

  const handleZoomIn = async () => {
    const nextZoom = Math.min(2.0, Math.round((zoomFactor + 0.1) * 10) / 10);
    setZoomFactor(nextZoom);
    try {
      await setBrowserZoom(tab.browserId, nextZoom);
    } catch {
      // ignore
    }
  };

  const handleZoomOut = async () => {
    const nextZoom = Math.max(0.5, Math.round((zoomFactor - 0.1) * 10) / 10);
    setZoomFactor(nextZoom);
    try {
      await setBrowserZoom(tab.browserId, nextZoom);
    } catch {
      // ignore
    }
  };

  const handleFocus = async () => {
    try {
      await focusBrowser(tab.browserId);
    } catch {
      // ignore
    }
  };

  const handleSyncState = async () => {
    try {
      const state = await getBrowserState(tab.browserId);
      if (state.url && state.url !== inputUrl) {
        setInputUrl(state.url);
      }
    } catch {
      // ignore
    }
  };

  return (
    <div className="flex items-center gap-2 px-3 py-1.5 bg-sidebar border-b border-border text-xs text-foreground select-none">
      <div className="flex items-center gap-1">
        <button
          type="button"
          disabled={!tab.canGoBack}
          onClick={onGoBack}
          aria-label="Back"
          className="p-1 rounded hover:bg-muted disabled:opacity-30 transition-colors"
        >
          <ArrowLeft className="w-3.5 h-3.5" />
        </button>
        <button
          type="button"
          disabled={!tab.canGoForward}
          onClick={onGoForward}
          aria-label="Forward"
          className="p-1 rounded hover:bg-muted disabled:opacity-30 transition-colors"
        >
          <ArrowRight className="w-3.5 h-3.5" />
        </button>
        <button
          type="button"
          onClick={onReload}
          aria-label="Reload"
          className="p-1 rounded hover:bg-muted transition-colors"
        >
          <RotateCw className={`w-3.5 h-3.5 ${tab.loading ? "animate-spin" : ""}`} />
        </button>
      </div>

      <form onSubmit={handleSubmit} className="flex-1 flex items-center">
        <input
          type="text"
          value={inputUrl}
          onChange={(e) => setInputUrl(e.target.value)}
          placeholder="Search or enter URL"
          aria-label="URL address bar"
          className="w-full bg-background border border-border rounded px-2.5 py-1 text-xs text-foreground focus:outline-none focus:border-primary font-mono"
        />
      </form>

      <div className="flex items-center gap-0.5 border-l border-border/70 pl-1.5">
        <button
          type="button"
          onClick={handleZoomOut}
          title="Zoom out"
          aria-label="Zoom out"
          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
        >
          <ZoomOut className="w-3.5 h-3.5" />
        </button>
        <span className="font-mono text-[10px] text-muted-foreground w-8 text-center">
          {Math.round(zoomFactor * 100)}%
        </span>
        <button
          type="button"
          onClick={handleZoomIn}
          title="Zoom in"
          aria-label="Zoom in"
          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
        >
          <ZoomIn className="w-3.5 h-3.5" />
        </button>
      </div>

      <div className="flex items-center gap-0.5 border-l border-border/70 pl-1.5">
        <button
          type="button"
          onClick={handleFocus}
          title="Focus webview"
          aria-label="Focus webview"
          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
        >
          <Target className="w-3.5 h-3.5" />
        </button>
        <button
          type="button"
          onClick={handleSyncState}
          title="Sync browser state"
          aria-label="Sync browser state"
          className="p-1 rounded hover:bg-muted text-muted-foreground hover:text-foreground transition-colors"
        >
          <RefreshCw className="w-3.5 h-3.5" />
        </button>
        <button
          type="button"
          onClick={handleExternalOpen}
          title="Open in default browser"
          aria-label="Open in external browser"
          className="p-1 rounded hover:bg-muted transition-colors"
        >
          <ExternalLink className="w-3.5 h-3.5 text-muted-foreground" />
        </button>
      </div>
    </div>
  );
}

import type { ButtonHTMLAttributes, ReactNode } from "react";

import { cn } from "../../lib/cn";

type IconButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  label: string;
  children: ReactNode;
  size?: "sm" | "md";
};

export function IconButton({
  label,
  children,
  className,
  size = "md",
  type = "button",
  ...props
}: IconButtonProps) {
  return (
    <button
      type={type}
      aria-label={label}
      title={label}
      className={cn(
        "inline-flex shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors",
        "hover:bg-accent hover:text-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
        "disabled:pointer-events-none disabled:opacity-40",
        size === "sm" ? "size-6" : "size-7",
        className,
      )}
      {...props}
    >
      {children}
    </button>
  );
}

import type { ReactNode } from "react";

import { cn } from "../../lib/cn";

type SectionHeaderProps = {
  title: string;
  count?: number;
  actions?: ReactNode;
  className?: string;
};

export function SectionHeader({ title, count, actions, className }: SectionHeaderProps) {
  return (
    <div className={cn("flex h-8 items-center justify-between gap-2 px-2", className)}>
      <div className="flex min-w-0 items-center gap-1.5 pl-2 text-xs font-semibold text-muted-foreground/80">
        <span className="truncate">{title}</span>
        {count !== undefined ? (
          <span className="rounded-full bg-sidebar-accent px-1.5 py-0.5 text-[10px] leading-none text-muted-foreground">
            {count}
          </span>
        ) : null}
      </div>
      {actions ? <div className="flex shrink-0 items-center gap-1">{actions}</div> : null}
    </div>
  );
}

import { LoaderCircle } from "lucide-react";

import { cn } from "../../lib/cn";
import type { TerminalActivityState } from "../../lib/activity";
import type { AgentState } from "../../lib/types";

export type StatusDotState = AgentState | TerminalActivityState | "unread";

type StatusDotProps = {
  state: StatusDotState;
  className?: string;
};

export function StatusDot({ state, className }: StatusDotProps) {
  if (state === "working") {
    return (
      <LoaderCircle
        aria-hidden="true"
        data-status-state="working"
        className={cn("size-3 shrink-0 animate-spin text-status-working motion-reduce:animate-none", className)}
      />
    );
  }

  if (state === "starting") {
    return (
      <span
        aria-hidden="true"
        data-status-state="starting"
        className={cn("size-2 shrink-0 animate-pulse rounded-full bg-status-warning motion-reduce:animate-none", className)}
      />
    );
  }

  if (state === "waiting") {
    return (
      <span
        aria-hidden="true"
        data-status-state="waiting"
        className={cn("size-2 shrink-0 rounded-full bg-status-warning ring-2 ring-status-warning/20", className)}
      />
    );
  }

  if (state === "unread") {
    return (
      <span
        aria-hidden="true"
        data-status-state="unread"
        className={cn("size-2 shrink-0 rounded-full bg-primary", className)}
      />
    );
  }

  if (state === "done" || state === "exited") {
    return (
      <span
        aria-hidden="true"
        data-status-state="done"
        className={cn("size-2 shrink-0 rounded-full bg-status-success", className)}
      />
    );
  }

  return (
    <span
      aria-hidden="true"
      data-status-state="failed"
      className={cn("size-2 shrink-0 rounded-full bg-destructive", className)}
    />
  );
}

