}

export async function getTerminalPreferences(): Promise<TerminalPreferences> {
  if (!isTauri()) {
    if (getRemoteAuthToken()) {
      try {
        return await defaultRemoteClient.fetchJson<TerminalPreferences>("/api/v1/terminal/preferences");
      } catch {
        // Fallback below
      }
    }
    return {
